// Class A.I. tutor -- the per-week guide for the COLG youth class "Learning
// A.I. The Way." SOVEREIGN + LOCAL: routes to Ollama on the NAS (model
// qwen2.5). No vendor LLM is called here; vendor escalation, if ever added,
// is a separate governed branch per the Charter. Single call, output-capped
// -- no loop, no runaway (the PWA client is user-triggered, not a timer).
//
// Request body (from app/src/lib/class-tutor.js buildTutorPayload):
//   { model, week, system, messages:[{role,content}] }
// Response: { ok, reply, source:'local' } or { ok:false, error }.
//
// OLLAMA_BASE: from INSIDE the n8n container the host LAN IP is NOT routable;
// reach Ollama via host.docker.internal (n8n extra_hosts host-gateway), the
// same path wf-llm-health uses (verified 2026-06-15).

const fs = require('fs');

const OLLAMA_BASE = 'http://host.docker.internal:11434';
const BEARER_FILE = '/home/node/.n8n/n8n-webhook-bearer.txt';
const ALLOWED_MODELS = ['qwen2.5', 'qwen2.5:latest', 'qwen2.5:7b'];
const DEFAULT_MODEL = 'qwen2.5';
const MAX_MESSAGES = 24;       // bound the context the client can push
const NUM_PREDICT = 512;       // output-token cap (budget brake)

function readSecret(p) {
  try { return fs.readFileSync(p, 'utf8').trim(); } catch (e) { return ''; }
}

const input = $input.first().json || {};
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

// Bearer gate (defense in depth; the NAS being LAN/Funnel-only is the real
// boundary). If no bearer file exists, the check is skipped.
const expected = readSecret(BEARER_FILE);
const auth = String(headers.authorization || headers.Authorization || '');
const presented = auth.replace(/^Bearer\s+/i, '').trim();
if (expected && presented !== expected) {
  return [{ json: { ok: false, error: 'unauthorized' } }];
}

// Pin the model to the sovereign local one regardless of what the client asks.
let model = String(body.model || DEFAULT_MODEL);
if (!ALLOWED_MODELS.includes(model)) model = DEFAULT_MODEL;

const system = String(body.system || 'You are a patient A.I. tutor for a church youth class. Be warm, brief, and never just hand over the answer.');
const rawMsgs = Array.isArray(body.messages) ? body.messages : [];
const convo = rawMsgs
  .filter(m => m && m.content)
  .slice(-MAX_MESSAGES)
  .map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: String(m.content).slice(0, 4000) }));

if (convo.length === 0) {
  return [{ json: { ok: false, error: 'no message' } }];
}

const messages = [{ role: 'system', content: system }].concat(convo);

let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: OLLAMA_BASE + '/api/chat',
    json: true,
    timeout: 45000,
    body: { model, messages, stream: false, options: { num_predict: NUM_PREDICT, temperature: 0.4 } },
  });
} catch (e) {
  return [{ json: { ok: false, error: 'ollama unreachable: ' + String(e && e.message || e) } }];
}

const reply = (res && res.message && res.message.content) ? String(res.message.content).trim() : '';
if (!reply) {
  return [{ json: { ok: false, error: 'empty reply' } }];
}

return [{ json: { ok: true, reply, source: 'local', model } }];
